class Solution {
    public int characterReplacement(String s, int k) {
        int[] count = new int[26];
        int maxCount = 0; // Max frequency of any single character in window
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < s.length(); right++) {
            count[s.charAt(right) - 'A']++;
            maxCount = Math.max(maxCount, count[s.charAt(right) - 'A']);

            // If window invalid (need more than k replacements), shrink
            while (right - left + 1 - maxCount > k) {
                count[s.charAt(left) - 'A']--;
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

class Solution {
    public int characterReplacement(String s, int k) {
        int[] count = new int[26];
        int maxCount = 0;
        int left = 0;
        int maxLen = 0;

        for (int right = 0; right < s.length(); right++) {
            count[s.charAt(right) - 'A']++;
            maxCount = Math.max(maxCount, count[s.charAt(right) - 'A']);

            // Window size = right - left + 1
            // Characters to replace = windowSize - maxCount
            if (right - left + 1 - maxCount > k) {
                // Slide window (don't shrink)
                count[s.charAt(left) - 'A']--;
                left++;
            }

            maxLen = right - left + 1;
        }

        return maxLen;
    }
}

class Solution {
    public int characterReplacement(String s, int k) {
        int answer = 0;

        for (char target = 'A'; target <= 'Z'; target++) {
            int left = 0;
            int replacementsNeeded = 0;

            for (int right = 0; right < s.length(); right++) {
                if (s.charAt(right) != target) {
                    replacementsNeeded++;
                }

                while (replacementsNeeded > k) {
                    if (s.charAt(left) != target) {
                        replacementsNeeded--;
                    }
                    left++;
                }

                answer = Math.max(answer, right - left + 1);
            }
        }

        return answer;
    }
}

class Solution {
    public int characterReplacement(String s, int k) {
        int left = 1;
        int right = s.length();
        int answer = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (hasValidWindow(s, k, mid)) {
                answer = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return answer;
    }

    private boolean hasValidWindow(String s, int k, int length) {
        int[] count = new int[26];
        for (int right = 0; right < s.length(); right++) {
            count[s.charAt(right) - 'A']++;
            if (right >= length) {
                count[s.charAt(right - length) - 'A']--;
            }
            if (right >= length - 1) {
                int maxCount = 0;
                for (int value : count) {
                    maxCount = Math.max(maxCount, value);
                }
                if (length - maxCount <= k) {
                    return true;
                }
            }
        }
        return false;
    }
}
